-- Resources content for Editorial Planning's reworked screens (CLAUDE.md, "Resources stay in step
-- with the code"). Content only; no schema. The prefix continues the sequence past 20261104130000;
-- see 20261103120000's header on why the prefix is a sequence number, not a date.
--
-- What changed for a reader: the Backlog's "This week" band, search plus one Filter menu (status
-- chips, pillar/format/urgency lists), the On slate / Stale badges; the Meetings tab as a table with
-- an inline New meeting card; the meeting page's slate list (a strip on a phone), "Save and go to
-- next unscored", anchor text on hover or under the scale on touch, the Decision select + Record,
-- the amber Split badge, the summary strip and Conclude meeting as the primary action with a
-- confirmation; the pitch page's "Where it stands" summary, compact review history and ⋮ menu.

select private.rc_release_guide(
  p_slug => 'editorial-submit-a-pitch',
  p_tool_key => 'editorial-planning',
  p_title => 'Submit a pitch',
  p_summary => 'Put a story idea in the backlog and follow how it''s decided.',
  p_screen_keys => array['editorial.backlog', 'editorial.pitch'],
  p_sort_order => 10,
  p_version_note => 'The This week band, search and Filter, and the pitch page''s Where it stands and ⋮ menu',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every story idea starts as a pitch in the backlog. An editor picks pitches from the backlog for a weekly planning meeting, where reviewers score them and the editor records a decision."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Submit one"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the Backlog tab, select "},{"type":"text","text":"New pitch","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Give it a title — one line that says what the story is — and fill in the fields below it. Fields marked with an asterisk are required."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose a "},{"type":"text","text":"Primary coverage pillar","marks":[{"type":"bold"}]},{"type":"text","text":". If you choose one of the station's pillars, say how the story contributes to sustained coverage of it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Submit pitch","marks":[{"type":"bold"}]},{"type":"text","text":". You land on the pitch's own page."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find a pitch in the backlog"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The band at the top of the Backlog says where this week's meeting stands and what you can do next: start or continue scoring, or, for an editor, build the slate, close scoring or conclude. It is not shown between meetings."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Type in "},{"type":"text","text":"Search pitches","marks":[{"type":"bold"}]},{"type":"text","text":" to find a pitch by its title or any of its answers. "},{"type":"text","text":"Filter","marks":[{"type":"bold"}]},{"type":"text","text":" holds the status chips — Open, Stale, Assigned and Archived, each with a count — and the Pillar, Format and Urgency lists."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A pitch marked "},{"type":"text","text":"On slate","marks":[{"type":"bold"}]},{"type":"text","text":" is on the current meeting; "},{"type":"text","text":"Stale","marks":[{"type":"bold"}]},{"type":"text","text":" means it has gone 90 days without a review or has been deferred three times. Editors can archive stale pitches in bulk from the Stale view."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit it"}]},{"type":"paragraph","content":[{"type":"text","text":"You can keep editing your pitch with "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" until an editor adds it to a meeting's slate. While that meeting is scoring, edits are locked; they reopen if the pitch comes back to the backlog."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Follow it"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The pitch page opens with the summary, then the other answers. "},{"type":"text","text":"Where it stands","marks":[{"type":"bold"}]},{"type":"text","text":", on the right, shows the status, which meeting it is on, how many meetings have reviewed it, the last decision and whether edits are open."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review history","marks":[{"type":"bold"}]},{"type":"text","text":" lists each meeting that discussed the pitch with its adjusted score and decision; open "},{"type":"text","text":"Scores, decision and comments","marks":[{"type":"bold"}]},{"type":"text","text":" for the breakdown, reviewers' comments and the rationale."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Editors use the ⋮ menu on a pitch to add it to the open slate, archive it with an optional reason, or restore an archived pitch to the backlog."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once a pitch is assigned, the page shows who is reporting it. The pipeline ends there; reporting itself is not tracked in this tool."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'editorial-run-a-planning-meeting',
  p_tool_key => 'editorial-planning',
  p_title => 'Run a planning meeting',
  p_summary => 'Build a slate, score it independently, then decide from the ranked agenda.',
  p_screen_keys => array['editorial.meeting'],
  p_sort_order => 20,
  p_version_note => 'The slate list and strip, Save and go to next unscored, the Decision select, and Conclude as the main action',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A planning meeting moves through three stages: Scoring open, Agenda, and Concluded. Editors run it; reviewers and editors score; contributors can follow along. The Meetings tab lists every meeting with its slate, filtered by In progress or Concluded."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Set it up (editors)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the Meetings tab, select "},{"type":"text","text":"New meeting","marks":[{"type":"bold"}]},{"type":"text","text":", choose the date and select "},{"type":"text","text":"Create meeting","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the meeting. Select "},{"type":"text","text":"+ Add pitch","marks":[{"type":"bold"}]},{"type":"text","text":" above the slate, choose a pitch from the backlog and select "},{"type":"text","text":"Add to slate","marks":[{"type":"bold"}]},{"type":"text","text":". Repeat for each pitch. A pitch can also be added from its own page's ⋮ menu."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Score the slate (reviewers and editors)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The slate is a list beside the pitch: a filled dot marks each pitch you have scored. On a phone the list becomes a strip above the pitch, with "},{"type":"text","text":"Previous","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Next","marks":[{"type":"bold"}]},{"type":"text","text":" and a picker. "},{"type":"text","text":"Show the full pitch","marks":[{"type":"bold"}]},{"type":"text","text":" expands the answers below the summary."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose a score for each criterion. On a computer, hover a number to read what it means; on a touch screen the meaning of the chosen number is shown under the scale. Institutional modifiers are optional."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose a recommendation, flag any concerns, and add a comment if it helps the room. "},{"type":"text","text":"Save review","marks":[{"type":"bold"}]},{"type":"text","text":" saves and stays; "},{"type":"text","text":"Save and go to next unscored","marks":[{"type":"bold"}]},{"type":"text","text":" saves and opens the next pitch you have not scored."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scoring is independent: nobody sees anyone else's scores or comments until the editor closes scoring."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Decide (editors)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Close scoring & build agenda","marks":[{"type":"bold"}]},{"type":"text","text":". The slate is ranked by adjusted score, and the strip at the top counts pitches, reviews and decisions made."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An amber "},{"type":"text","text":"Split","marks":[{"type":"bold"}]},{"type":"text","text":" badge means reviewers' core scores are far apart — worth discussing. Open "},{"type":"text","text":"Scores, recommendations and comments","marks":[{"type":"bold"}]},{"type":"text","text":" to see why."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For each pitch, choose a "},{"type":"text","text":"Decision","marks":[{"type":"bold"}]},{"type":"text","text":" — Assign, Defer or Archive — and select "},{"type":"text","text":"Record","marks":[{"type":"bold"}]},{"type":"text","text":". Assign asks for the reporter; Defer and Archive take an optional rationale. A decided pitch shows its outcome; select "},{"type":"text","text":"Change","marks":[{"type":"bold"}]},{"type":"text","text":" to revise it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Conclude meeting","marks":[{"type":"bold"}]},{"type":"text","text":" is the main action once the agenda is built. It asks you to confirm and names any pitch still undecided, which is recorded as deferred. A concluded meeting is a permanent record."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-28-editorial-screens',
  p_tool_key => 'editorial-planning',
  p_released_on => '2026-10-28',
  p_title => 'Editorial Planning screens reworked',
  p_guide_slugs => array['editorial-submit-a-pitch', 'editorial-run-a-planning-meeting'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Editorial Planning screens were reworked. The Backlog opens with a This week band that says where the current meeting stands, and its filters — status, pillar, format and urgency — sit behind one Filter button next to a search box. The Meetings tab is a table with each meeting's slate. On the meeting page, scorers move through the slate from a list beside the pitch (a strip on a phone) and can save and go straight to the next unscored pitch; score meanings show on hover on a computer and under the scale on a touch screen. The agenda records a decision with one Decision choice and a Record button, and Conclude meeting is the page's main action, with a confirmation that names anything undecided. The pitch page gains a Where it stands summary and a ⋮ menu for adding to the slate, archiving and restoring."}]}]}$body$
);
